import osimport zipfileimport shutildef find_log_file(directory, folder_name):    """Search for the expected .log file within a directory recursively."""    for root, _, files in os.walk(directory):        for file in files:            if file == f"{folder_name}.log":                return os.path.join(root, file)    return Nonedef process_subfolders(parent_folder):    # Get list of subfolders in the parent folder    subfolders = [        os.path.join(parent_folder, subfolder) for subfolder in os.listdir(parent_folder)        if os.path.isdir(os.path.join(parent_folder, subfolder))    ]    for folder in subfolders:        folder_name = os.path.basename(folder)        # Locate scenario_X.zip file        zip_file_path = os.path.join(folder, f"dynamic_data_{folder_name}.zip")        if not os.path.isfile(zip_file_path):            print(f"ZIP file not found in folder: {folder}")            continue        # Extract scenario_X.zip        extract_dir = os.path.join(folder, "temp_extracted")        if not os.path.exists(extract_dir):            os.makedirs(extract_dir)        try:            with zipfile.ZipFile(zip_file_path, 'r') as zip_ref:                zip_ref.extractall(extract_dir)                print(f"Extracted {zip_file_path} to {extract_dir}")        except zipfile.BadZipFile:            print(f"Error: {zip_file_path} is not a valid ZIP file.")            continue        # Search for the expected .log file        old_file_path = find_log_file(extract_dir, f"dynamic_data_{folder_name}")        if not old_file_path:            print(f"Expected file not found after extraction: {folder_name}.log in {extract_dir}")            shutil.rmtree(extract_dir)  # Clean up            continue        # Rename contained file x.log to x.zip        new_file_path = os.path.join(extract_dir, f"dynamic_data_{folder_name}.json")        os.rename(old_file_path, new_file_path)        # Re-zip the renamed file        final_zip_path = os.path.join(folder, f"dynamic_data_{folder_name}.zip")        with zipfile.ZipFile(final_zip_path, 'w') as zip_out:            zip_out.write(new_file_path, arcname=os.path.basename(new_file_path))            print(f"Created final ZIP: {final_zip_path}")        # Clean up temporary directory        shutil.rmtree(extract_dir)        print(f"Processed folder: {folder}")# Example usageparent_folder = "processed_scenarios"  # Replace with the path to your parent folderprocess_subfolders(parent_folder)